{"content":"extends Node
## Moving-receiver projected decal reference implementation.
## The numerical path is deterministic and mirrors the fixed planar receiver;
## the visual path is attached to the actual TargetA scene node.

var scene_root: Node
var test_input: Dictionary = {}
var elapsed_s := 0.0
var current_step := 0
var event_active := false
var hit_data: Dictionary = {}
var projector: Dictionary = {}
var surface: Dictionary = {}
var lifetime_s := 2.0
var samples: Array = []
var target_name := "target_a"
var _visual_decal: Decal
var _visual_target: Node3D
var _event_id := -1

func _vec3(a: Array) -> Vector3:
	return Vector3(float(a[0]), float(a[1]), float(a[2]))

func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	elapsed_s = 0.0; current_step = 0; samples.clear()
	surface = inputs.get("surface", {})
	projector = inputs.get("projector", {})
	hit_data = inputs.get("hit", {}).duplicate(true)
	lifetime_s = float(inputs.get("lifetime_s", 2.0))
	target_name = str(hit_data.get("target", "target_a"))
	_event_id = int(hit_data.get("event_id", -1))
	event_active = _target_allowed(target_name)
	_install_visual_decal()

func setup(context: Dictionary) -> void:
	if test_input.is_empty(): configure(context.get("root", self), _default_input())
	else: scene_root = context.get("root", scene_root)

func reset(_state: Dictionary = {}) -> void:
	elapsed_s = 0.0; current_step = 0; samples.clear()
	event_active = _target_allowed(target_name)
	if is_instance_valid(_visual_decal): _visual_decal.visible = event_active

func step(dt: float, _state: Dictionary = {}) -> void:
	elapsed_s += dt
	current_step += 1
	if elapsed_s >= lifetime_s: event_active = false
	_update_visual_decal()
	if is_instance_valid(_visual_decal): _visual_decal.visible = event_active

func on_event(_event_name: String, payload: Dictionary, _state: Dictionary = {}) -> void:
	var incoming_id := int(payload.get("event_id", -1))
	# A repeated event is not a new hit and cannot extend the lifetime.
	if incoming_id == _event_id and incoming_id >= 0: return
	if not payload.is_empty():
		for k in payload: hit_data[k] = payload[k]
	target_name = str(hit_data.get("target", target_name))
	_event_id = incoming_id
	elapsed_s = 0.0
	event_active = _target_allowed(target_name)
	_update_visual_decal()

func _target_allowed(name: String) -> bool:
	return name in test_input.get("allowed_targets", ["target_a", "target_b"])

func _target_node() -> Node3D:
	if scene_root == null: return null
	var wanted := "TargetA" if target_name.to_lower() == "target_a" else "TargetB"
	return scene_root.find_child(wanted, true, false) as Node3D

func _hit_world_position() -> Vector3:
	var target := _target_node()
	var local := _vec3(hit_data.get("local_position", [0,0,0]))
	if target != null: return target.global_transform * local
	return local

func _hit_world_normal() -> Vector3:
	var target := _target_node()
	var n := _vec3(hit_data.get("local_normal", [0,0,1])).normalized()
	if target != null: return (target.global_transform.basis * n).normalized()
	return n

func _smooth_orientation(cosine: float) -> float:
	var lo := float(projector.get("cos_reject", 0.2))
	var hi := float(projector.get("cos_full", 0.8))
	return smoothstep(lo, hi, clamp(cosine, 0.0, 1.0))

func _default_input() -> Dictionary:
	return {"viewport":[128,128], "camera":{"eye":[0,0,4],"target":[0,0,0],"up":[0,1,0],"fov_degrees":60.0}, "surface":{"vertices":[[-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0]],"triangles":[[0,1,2],[0,2,3]],"albedo_linear":[0.5,0.5,0.5]}, "projector":{"origin":[0,0,0],"rotation_degrees":[0,0,0],"scale":[0.5,0.5,0.2],"cos_reject":0.2,"cos_full":0.8,"albedo_linear":[0.15,0.03,0.01],"opacity":0.8}, "hit":{"event_id":1,"target":"target_a","local_position":[0,0,0],"local_normal":[0,0,1]}, "lifetime_s":2.0}

func _make_mark_texture() -> Texture2D:
	var image := Image.create(128, 128, false, Image.FORMAT_RGBA8)
	for y in range(128):
		for x in range(128):
			var q := Vector2(float(x)-63.5, float(y)-63.5) / 63.5
			var edge := clamp((1.0-q.length())/0.12, 0.0, 1.0)
			image.set_pixel(x, y, Color(0.15,0.03,0.01,edge * 0.8))
	image.generate_mipmaps()
	return ImageTexture.create_from_image(image)

func _install_visual_decal() -> void:
	if scene_root == null: return
	_visual_target = _target_node()
	if _visual_target == null: return
	if _visual_decal == null:
		_visual_decal = Decal.new()
		_visual_decal.name = "DepthReconstructedDecal"
		_visual_decal.texture_albedo = _make_mark_texture()
		_visual_decal.albedo_mix = 0.8
		_visual_decal.size = Vector3(1.0, 0.4, 1.0)
		_visual_decal.distance_fade_enabled = true
		_visual_decal.distance_fade_begin = 8.0
		_visual_decal.distance_fade_length = 4.0
		_visual_target.add_child(_visual_decal)
	_update_visual_decal()

func _update_visual_decal() -> void:
	if not is_instance_valid(_visual_decal): return
	# Decal local coordinates are target-local, so target motion is inherited.
	_visual_decal.position = _vec3(hit_data.get("local_position", [0,0,0])) + Vector3(0,0,0.03)
	_visual_decal.rotation_degrees = Vector3(90,0,0)

func _projector_local(world_position: Vector3) -> Vector3:
	var origin := _hit_world_position()
	var normal := _hit_world_normal()
	var tangent := Basis.looking_at(-normal, Vector3.UP)
	# For the supplied front-facing target, this is the same XY projector frame;
	# using the hit frame also handles moved/yawed receivers.
	var q := tangent.inverse() * (world_position - origin)
	var scale := _vec3(projector.get("scale", [0.5,0.5,0.2]))
	return Vector3(q.x/scale.x, q.y/scale.y, q.z/scale.z)

